class Solution {
public:
    vector<vector<int>> findRLEArray(vector<vector<int>>& encoded1,
                                     vector<vector<int>>& encoded2) {
        vector<vector<int>> answer;
        int i = 0, j = 0;
        int left = 0, right = 0;
        while (i < static_cast<int>(encoded1.size()) && j < static_cast<int>(encoded2.size())) {
            if (left == 0) left = encoded1[i][1];
            if (right == 0) right = encoded2[j][1];
            int count = min(left, right);
            int value = encoded1[i][0] * encoded2[j][0];
            if (!answer.empty() && answer.back()[0] == value) answer.back()[1] += count;
            else answer.push_back({value, count});
            left -= count;
            right -= count;
            if (left == 0) ++i;
            if (right == 0) ++j;
        }
        return answer;
    }
};
